module advanced_decimator_with_adaptive_peak_detection #(parameter N=8,DATA_WIDTH=16,DEC_FACTOR=4)(input clk,reset,valid_in,input [N*DATA_WIDTH-1:0] data_in,output reg valid_out,output reg [DATA_WIDTH*(N/DEC_FACTOR)-1:0] data_out,output reg signed [DATA_WIDTH-1:0] peak_value);
reg [N*DATA_WIDTH-1:0] samples;integer i;
always @(posedge clk or posedge reset)if(reset)begin samples<=0;valid_out<=0;end else begin samples<=data_in;valid_out<=valid_in;end
always @*begin peak_value=$signed(samples[(N-1)*DATA_WIDTH+:DATA_WIDTH]);data_out=0;for(i=0;i<N/DEC_FACTOR;i=i+1)begin data_out[(N/DEC_FACTOR-1-i)*DATA_WIDTH+:DATA_WIDTH]=samples[(N-1-i*DEC_FACTOR)*DATA_WIDTH+:DATA_WIDTH];if($signed(samples[(N-1-i*DEC_FACTOR)*DATA_WIDTH+:DATA_WIDTH])>peak_value)peak_value=$signed(samples[(N-1-i*DEC_FACTOR)*DATA_WIDTH+:DATA_WIDTH]);end end endmodule
